using System;
using System.Collections.Generic;
using UnityEngine;

namespace OndeVai.Gameplay
{
    /// <summary>How the collider of an item is built from its sprite.</summary>
    public enum ItemColliderShape
    {
        /// <summary>Uses the physics shape generated by the sprite importer. Falls back to a box when the sprite has none.</summary>
        PhysicsShape = 0,
        Box = 1,
        Circle = 2
    }

    /// <summary>Per variant collider choice.</summary>
    public enum ItemColliderOverride
    {
        UseTypeDefault = 0,
        PhysicsShape = 1,
        Box = 2,
        Circle = 3
    }

    /// <summary>
    /// One look of an item type (e.g. "bear" for Toys). Every variant is spawned from the same Item prefab.
    /// </summary>
    [Serializable]
    public sealed class ItemVariant
    {
        [Tooltip("Stable id saved in the history database. Defaults to the sprite name.")]
        public string Id;

        public Sprite Sprite;

        [Tooltip("Disabled variants are never spawned.")]
        public bool Enabled = true;

        [Tooltip("Relative chance of being picked among the variants of the type.")]
        [Min(0f)] public float Weight = 1f;

        [Tooltip("Multiplied with the type scale.")]
        [Min(0.05f)] public float Scale = 1f;

        public Color Tint = Color.white;

        public ItemColliderOverride Collider = ItemColliderOverride.UseTypeDefault;

        /// <summary>True when the variant can be spawned.</summary>
        public bool IsPlayable => Enabled && Sprite != null && Weight > 0f;

        /// <summary>Creates a variant with sensible defaults for a sprite.</summary>
        public static ItemVariant FromSprite(Sprite sprite)
        {
            return new ItemVariant { Id = sprite != null ? sprite.name : string.Empty, Sprite = sprite };
        }
    }

    /// <summary>
    /// A category of sortable items (Toys, Tools, Vowels...). Holds the category identity, the defaults
    /// shared by its items and the list of visual variants.
    /// </summary>
    [CreateAssetMenu(fileName = "ItemType", menuName = "Onde Vai/Item Type", order = 0)]
    public sealed class ItemTypeDefinition : ScriptableObject
    {
        [Header("Identity")]
        [Tooltip("Category key used by storages, scenarios and the history database.")]
        [SerializeField] private ItemGroup _group;

        [Tooltip("Name shown to parents and teachers (Portuguese).")]
        [SerializeField] private string _displayName;

        [Tooltip("Image that represents the group in swipe mode. The group icon is used when this is empty.")]
        [SerializeField] private Sprite _background;

        [Tooltip("Icon representing the category, e.g. above its storage. The first variant sprite is used when empty.")]
        [SerializeField] private Sprite _icon;

        [SerializeField] private Color _color = Color.white;

        [Header("Item defaults")]
        [SerializeField, Min(0.05f)] private float _scale = 1f;
        [Tooltip("Items shrink as they move up the screen to fake depth.")]
        [SerializeField] private bool _scaleWithDepth = true;
        [SerializeField] private ItemColliderShape _colliderShape = ItemColliderShape.PhysicsShape;
        [SerializeField, Min(0f)] private float _gravityScale = 1f;
        [SerializeField, Min(0.01f)] private float _mass = 1f;

        [Header("Variants")]
        [SerializeField] private List<ItemVariant> _variants = new();

        public ItemGroup Group => _group;
        public string DisplayName => string.IsNullOrEmpty(_displayName) ? _group.ToString() : _displayName;
        public Color Color => _color;
        public float Scale => _scale;
        public bool ScaleWithDepth => _scaleWithDepth;
        public float GravityScale => _gravityScale;
        public float Mass => _mass;
        public IReadOnlyList<ItemVariant> Variants => _variants;
        public Sprite Background => _background != null ? _background : Icon;

        /// <summary>The category icon, or the sprite of the first playable variant.</summary>
        public Sprite Icon
        {
            get
            {
                if (_icon != null)
                    return _icon;

                foreach (ItemVariant variant in _variants)
                {
                    if (variant != null && variant.IsPlayable)
                        return variant.Sprite;
                }

                return null;
            }
        }

        /// <summary>True when at least one variant can be spawned.</summary>
        public bool HasPlayableVariants
        {
            get
            {
                foreach (ItemVariant variant in _variants)
                {
                    if (variant != null && variant.IsPlayable)
                        return true;
                }

                return false;
            }
        }

        /// <summary>Finds a variant by its stable id. Returns null when the type has none with that id.</summary>
        public ItemVariant FindVariant(string id)
        {
            foreach (ItemVariant variant in _variants)
            {
                if (variant != null && variant.Id == id)
                    return variant;
            }

            return null;
        }

        /// <summary>Resolves the collider shape of a variant.</summary>
        public ItemColliderShape GetColliderShape(ItemVariant variant)
        {
            if (variant == null || variant.Collider == ItemColliderOverride.UseTypeDefault)
                return _colliderShape;

            return (ItemColliderShape)((int)variant.Collider - 1);
        }

        /// <summary>
        /// Picks a playable variant by weight, avoiding <paramref name="avoid"/> when another option exists.
        /// </summary>
        public bool TryPickVariant(ItemVariant avoid, out ItemVariant picked)
        {
            float total = 0f;
            int playable = 0;
            foreach (ItemVariant variant in _variants)
            {
                if (variant == null || !variant.IsPlayable)
                    continue;

                playable++;
                total += variant.Weight;
            }

            picked = null;
            if (playable == 0)
                return false;

            bool skipAvoided = avoid != null && avoid.IsPlayable && playable > 1;
            if (skipAvoided)
                total -= avoid.Weight;

            float roll = UnityEngine.Random.value * total;
            foreach (ItemVariant variant in _variants)
            {
                if (variant == null || !variant.IsPlayable || (skipAvoided && variant == avoid))
                    continue;

                picked = variant;
                roll -= variant.Weight;
                if (roll <= 0f)
                    break;
            }

            return picked != null;
        }

#if UNITY_EDITOR
        /// <summary>Editor only: appends variants for sprites that are not in the list yet. Returns how many were added.</summary>
        public int AddSprites(IEnumerable<Sprite> sprites)
        {
            int added = 0;
            foreach (Sprite sprite in sprites)
            {
                if (sprite == null || _variants.Exists(variant => variant != null && variant.Sprite == sprite))
                    continue;

                _variants.Add(ItemVariant.FromSprite(sprite));
                added++;
            }

            if (added > 0)
                OnValidate();

            return added;
        }

        /// <summary>Editor only: reorders the variant list.</summary>
        public void SortVariants(Comparison<ItemVariant> comparison)
        {
            _variants.Sort(comparison);
        }

        private void OnValidate()
        {
            HashSet<string> usedIds = new();
            foreach (ItemVariant variant in _variants)
            {
                if (variant == null)
                    continue;

                if (string.IsNullOrWhiteSpace(variant.Id) && variant.Sprite != null)
                    variant.Id = variant.Sprite.name;

                if (string.IsNullOrWhiteSpace(variant.Id))
                    continue;

                string baseId = variant.Id.Trim();
                string id = baseId;
                for (int suffix = 2; !usedIds.Add(id); suffix++)
                    id = $"{baseId}_{suffix}";

                variant.Id = id;
            }
        }
#endif
    }
}
